const STRINGS = {
  judgeTitle:{en:'Reviewer shortcut',hi:'Reviewer shortcut'}, judgeSub:{en:'One real path through the build: record → find → route. Uses only synthetic data.',hi:'Build का एक real path: record → find → route. केवल synthetic data का इस्तेमाल।'}, startWalkthrough:{en:'Start the 90-second walkthrough →',hi:'90-second walkthrough शुरू करें →'},
  brand:{en:'On Record',hi:'On Record'}, footer:{en:'On Record is an independent prototype. It is not affiliated with any government department.',hi:'On Record एक स्वतंत्र prototype है। यह किसी भी government department से affiliated नहीं है।'}, homeEyebrow:{en:'The family register / Index',hi:'Family register / Index'}, homeTitle:{en:'What is on record.',hi:'रिकॉर्ड में क्या है।'}, homeSub:{en:'A calm place to list an account, a nominee, a document — and see what to do next.',hi:'Account, nominee और document दर्ज करने की शांत जगह — और अगला कदम देखने के लिए।'}, promise:{en:'The name is the promise: we show what is currently on record, never what someone is legally entitled to.',hi:'नाम ही वादा है: हम वही दिखाते हैं जो अभी record में है, यह नहीं कि कोई legally किसका हकदार है।'}, sessionNote:{en:'No account · No login · Mock data only · Built with Codex',hi:'No account · No login · केवल mock data · Codex से built'}, stamp:{en:'RECORDED',hi:'दर्ज़'}, recordCode:{en:'OR / 2026',hi:'OR / 2026'}, d1:{en:'Organise & Protect',hi:'Organise & Protect'}, d1d:{en:'Make your own family record easier to find and keep up to date.',hi:'अपने family record को ढूंढना आसान बनाएं और up to date रखें।'}, d2:{en:"Find What's Lost",hi:'Find What’s Lost'}, d2d:{en:'Search a simulated index for money that may be waiting in another registry.',hi:'Simulated index में देखें कि शायद किसी दूसरे registry में पैसा दर्ज है।'}, d3:{en:'Know Your Rights',hi:'Know Your Rights'}, d3d:{en:'Understand the general rule and find the right place to ask next.',hi:'General rule समझें और अगला सवाल सही जगह ले जाएं।'}, back:{en:'← Back to index',hi:'← Index पर वापस'}, addTitle:{en:'Build your record',hi:'अपना record बनाएं'}, addSub:{en:'Add what you know. This stays in this browser session; no account or login is needed.',hi:'जो जानते हैं वह जोड़ें। यह इसी browser session में रहता है; account या login की जरूरत नहीं।'}, asset:{en:'Asset',hi:'Asset'}, type:{en:'Type',hi:'Type'}, institution:{en:'Institution name',hi:'Institution का नाम'}, nomineeSet:{en:'Nominee currently listed?',hi:'क्या nominee अभी record में है?'}, yes:{en:'Yes',hi:'हां'}, no:{en:'No',hi:'नहीं'}, nomineeName:{en:'Nominee name',hi:'Nominee का नाम'}, relation:{en:'Relation',hi:'Relation'}, updated:{en:'Last updated year',hi:'Last updated year'}, remove:{en:'Remove',hi:'हटाएं'}, addAsset:{en:'+ Add another asset',hi:'+ दूसरा asset जोड़ें'}, check:{en:'Check my record →',hi:'मेरा record check करें →'}, checkTitle:{en:'A first reading of your record',hi:'आपके record की पहली reading'}, checkSub:{en:'These are completeness signals, not legal conclusions.',hi:'ये completeness signals हैं, legal conclusions नहीं।'}, missing:{en:'Missing nominee',hi:'Nominee record में नहीं'}, outdated:{en:'Nominee may be outdated',hi:'Nominee पुराना हो सकता है'}, complete:{en:'On record, complete',hi:'Record में, complete'}, fixMissing:{en:"Fix: add a nominee at your bank's branch or net-banking nomination page.",hi:'Fix: अपने bank की branch या net-banking nomination page पर nominee जोड़ें।'}, fixOld:{en:'Fix: revisit and refresh the nominee details.',hi:'Fix: nominee details फिर से check करके update करें।'}, explainer:{en:'What a nominee record means',hi:'Nominee record का मतलब'}, handover:{en:'Make handover sheet →',hi:'Handover sheet बनाएं →'}, draft:{en:'Prepare a will draft',hi:'Will draft तैयार करें'}, optional:{en:'Optional path',hi:'Optional path'}, testator:{en:'Name of the person making this draft',hi:'Draft बनाने वाले व्यक्ति का नाम'}, beneficiary:{en:'Beneficiary',hi:'Beneficiary'}, whatThey:{en:'What they are described as receiving',hi:'उन्हें क्या मिलने का वर्णन है'}, addBeneficiary:{en:'+ Add beneficiary',hi:'+ Beneficiary जोड़ें'}, makeDraft:{en:'Create draft →',hi:'Draft बनाएं →'}, draftWarning:{en:'DRAFT — NOT LEGALLY VALID UNTIL PROPERLY EXECUTED',hi:'DRAFT — PROPERLY EXECUTED होने तक LEGALLY VALID नहीं'}, draftSub:{en:'This is a draft to take to a lawyer or the Sub-Registrar. It has no legal effect until properly executed and, where applicable, registered.',hi:'यह lawyer या Sub-Registrar को ले जाने के लिए draft है। Properly executed और जहां लागू हो registered होने तक इसका कोई legal effect नहीं है।'}, willChecklist:{en:'What the general checklist says',hi:'General checklist क्या कहती है'}, print:{en:'Print this draft',hi:'इस draft को print करें'}, sheetTitle:{en:'Handover sheet / What is currently on record',hi:'Handover sheet / अभी record में क्या है'}, sheetSub:{en:'A factual snapshot for the person who owns this record.',hi:'इस record के owner के लिए factual snapshot।'}, currentNominee:{en:'Nominee currently listed',hi:'अभी record में listed nominee'}, status:{en:'Status',hi:'Status'}, share:{en:'Share this sheet',hi:'यह sheet share करें'}, shareTitle:{en:'Before you share',hi:'Share करने से पहले'}, shareSub:{en:'This is exactly what will be shared with the named recipient:',hi:'Named recipient के साथ exactly यह share होगा:'}, recipient:{en:'Recipient name',hi:'Recipient का नाम'}, cancel:{en:'Cancel',hi:'Cancel'}, confirmShare:{en:'Confirm share',hi:'Share confirm करें'}, shared:{en:'Share recorded. It can be revoked in this session.',hi:'Share record हो गया। इस session में इसे revoke किया जा सकता है।'}, revoke:{en:'Revoke share',hi:'Share revoke करें'}, lostTitle:{en:"Find what's lost",hi:'जो खोया है उसे खोजें'}, lostSub:{en:'This is a fast, simulated cross-registry search. No government system is contacted.',hi:'यह fast, simulated cross-registry search है। किसी government system से संपर्क नहीं होता।'}, person:{en:'Person or family name',hi:'Person या family name'}, years:{en:'Approximate years (optional)',hi:'Approximate years (optional)'}, search:{en:'Search the five registries →',hi:'पांच registries में खोजें →'}, searching:{en:'Checking',hi:'Checking'}, matches:{en:'Possible matches in the mock index',hi:'Mock index में possible matches'}, viewChecklist:{en:'See claim checklist →',hi:'Claim checklist देखें →'}, strong:{en:'Strong match',hi:'Strong match'}, possible:{en:'Possible match',hi:'Possible match'}, simulated:{en:'This search is simulated for this prototype. A real version would need direct, authorised data-sharing agreements with RBI, IRDAI, SEBI and EPFO, the same institutions the government’s own portal already links out to.',hi:'यह search इस prototype के लिए simulated है। Real version के लिए RBI, IRDAI, SEBI और EPFO के साथ direct, authorised data-sharing agreements चाहिए होंगे; government का अपना portal भी इन्हीं institutions के links देता है।'}, claimTitle:{en:'If this match is yours to follow up',hi:'अगर इस match पर follow up करना हो'}, claimNote:{en:'This is a general document checklist, not a decision about a claim.',hi:'यह general document checklist है, किसी claim पर decision नहीं।'}, rightsTitle:{en:'What is your situation?',hi:'आपकी situation क्या है?'}, rightsSub:{en:'Choose a path. This is a fixed decision tree, not a chatbot.',hi:'एक path चुनें। यह fixed decision tree है, chatbot नहीं।'}, lostRelative:{en:'A relative may have left something unclaimed',hi:'किसी relative की unclaimed चीज हो सकती है'}, setup:{en:'I am worried about my family’s setup',hi:'मुझे अपने family setup की चिंता है'}, pressure:{en:'I feel pressured about my property',hi:'मेरी property को लेकर मुझ पर pressure है'}, dispute:{en:'There is already a dispute',hi:'पहले से dispute है'}, next:{en:'What to do next',hi:'अगला कदम'}, escalation:{en:'Places that handle disputes',hi:'Dispute संभालने वाली जगहें'}, verify:{en:'Confirm before relying on this',hi:'भरोसा करने से पहले confirm करें'}, generalRule:{en:'This explains the general rule. It does not decide your specific case. Confirm with a lawyer or the relevant office.',hi:'यह general rule समझाता है। यह आपकी specific case का फैसला नहीं करता। Lawyer या relevant office से confirm करें।'}, noAssets:{en:'No assets added yet.',hi:'अभी कोई asset नहीं जोड़ा गया।'}, noMatches:{en:'No matches in this mock index.',hi:'इस mock index में कोई match नहीं मिला।'}
};
Object.assign(STRINGS, {
  familyEyebrow:{en:'Family continuity / A shared starting point',hi:'Family continuity / एक साझा शुरुआत'},
  familyTitle:{en:'When a family member is gone, confusion becomes conflict.',hi:'जब परिवार का कोई सदस्य नहीं रहता, तो confusion conflict बन जाता है।'},
  familySub:{en:'On Record helps families prepare before that moment, organise the handover after it, and find the right place to resolve what is contested.',hi:'On Record परिवार को उस moment से पहले prepare करने, उसके बाद handover organise करने और contested बातों के लिए सही जगह तक पहुंचने में मदद करता है।'},
  familyPromise:{en:'Know what exists. Know what is missing. Know what to do next.',hi:'क्या मौजूद है जानें। क्या missing है जानें। अगला कदम जानें।'},
  independent:{en:'An independent prototype for a future government-mediated service · synthetic data only',hi:'Future government-mediated service के लिए independent prototype · केवल synthetic data'},
  prepareTitle:{en:'Prepare',hi:'Prepare'}, prepareDesc:{en:'Record property, money, nominees, documents, and declared wishes before a crisis.',hi:'Crisis से पहले property, money, nominee, documents और declared wishes record करें।'},
  handoverTitle:{en:'Handover',hi:'Handover'}, handoverDesc:{en:'After a death, turn scattered papers into a clear list of documents and next steps.',hi:'Death के बाद scattered papers को documents और next steps की clear list में बदलें।'},
  resolveTitle:{en:'Resolve',hi:'Resolve'}, resolveDesc:{en:'When something is contested, make a neutral summary and reach the right authority.',hi:'जब कोई बात contested हो, neutral summary बनाएं और सही authority तक पहुंचें।'},
  startPrepare:{en:'Start a family record →',hi:'Family record शुरू करें →'}, startHandover:{en:'Start a handover →',hi:'Handover शुरू करें →'}, startResolve:{en:'Find the right route →',hi:'सही route खोजें →'},
  handoverEyebrow:{en:'Handover / after a death',hi:'Handover / death के बाद'}, handoverTitle:{en:'Make the first days less confusing.',hi:'पहले दिनों का confusion कम करें।'}, handoverSub:{en:'Start with what you know. This prototype shows the documents, possible records, and next authorities a family may need to consider.',hi:'जो जानते हैं उससे शुरू करें। यह prototype documents, possible records और next authorities दिखाता है जिन पर family को विचार करना पड़ सकता है।'}, handoverStep1:{en:'1. Gather the record',hi:'1. Record इकट्ठा करें'}, handoverStep2:{en:'2. Check what may be missing',hi:'2. देखें क्या missing हो सकता है'}, handoverStep3:{en:'3. Take the packet to the right place',hi:'3. Packet सही जगह ले जाएं'},
  mockBoundary:{en:'This is a simulated journey. It does not access government systems or decide inheritance.',hi:'यह simulated journey है। यह government systems access नहीं करता और inheritance का फैसला नहीं करता।'}
});
const state = { lang: new URLSearchParams(location.search).get('lang') === 'hi' ? 'hi' : 'en', assets: [], beneficiaries: [], testator: '', search: null, share: null };
const $ = (s) => document.querySelector(s); const t = (k) => String(STRINGS[k]?.[state.lang] || STRINGS[k]?.en || k).replace(/\s*—\s*/g, ', ');
const esc = (v='') => String(v).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const typeLabel = (type) => { const a=ASSET_TYPES.find(x=>x[0]===type); return a ? a[state.lang==='hi'?2:1] : type; };
const verify = (f) => f.confidence === 'verify' ? `<span class="verify">◌ ${t('verify')}</span>` : '';
function go(path){ location.hash = path; }
function setLang(lang){ state.lang=lang; const q=new URLSearchParams(location.search); q.set('lang',lang); history.replaceState(null,'',location.pathname+'?'+q.toString()+location.hash); render(); }
function updateAsset(i,k,v){ state.assets[i][k]=v; render(); }
function addAsset(){ state.assets.push({type:'bank', institution:'', hasNominee:false, nominee:'', relation:'', year:''}); render(); }
function startWalkthrough(){ state.assets=[{type:'bank',institution:'State Bank of India',hasNominee:false,nominee:'',relation:'',year:''},{type:'insurance',institution:'LIC',hasNominee:true,nominee:'Meera Sharma',relation:'Daughter',year:'2025'}]; state.search=null; state.share=null; go('/door1/check'); }
function removeAsset(i){ state.assets.splice(i,1); render(); }
function completeness(a){ if(!a.hasNominee) return 'missing'; if(a.year && 2026-Number(a.year)>5) return 'outdated'; return 'complete'; }
function status(s){ return `<span class="status ${s}">${s==='missing'?'!':s==='outdated'?'◌':'✓'} ${t(s)}</span>`; }
function layout(content){ document.documentElement.lang=state.lang==='hi'?'hi':'en'; $('#lang-en').classList.toggle('active',state.lang==='en'); $('#lang-hi').classList.toggle('active',state.lang==='hi'); document.querySelectorAll('[data-i18n]').forEach(el=>el.textContent=t(el.dataset.i18n)); $('#app').innerHTML=content; $('#app').focus(); }
function home(){ return `<section class="hero"><div><div class="eyebrow">${t('homeEyebrow')}</div><h1>${t('homeTitle')}</h1><p class="hero-copy">${t('homeSub')}</p></div><div><div class="promise">${t('promise')}</div><p class="note">${t('sessionNote')}</p></div></section><section class="register"><div class="register-title">${t('homeEyebrow')}</div>${[['01','d1','d1d','/door1/add'],['02','d2','d2d','/door2/search'],['03','d3','d3d','/door3']].map(x=>`<a class="door" href="#${x[3]}"><span class="door-number">${x[0]}</span><span><span class="door-title">${t(x[1])}</span><span class="door-desc">${t(x[2])}</span></span><span class="door-arrow" aria-hidden="true">↗</span></a>`).join('')}</section>`; }
function assetForm(a,i){ return `<article class="asset-card"><span class="asset-index mono">${String(i+1).padStart(2,'0')}</span><div class="fields"><div class="field"><label for="type-${i}">${t('type')}</label><select id="type-${i}" onchange="updateAsset(${i},'type',this.value)">${ASSET_TYPES.map(x=>`<option value="${x[0]}" ${a.type===x[0]?'selected':''}>${x[state.lang==='hi'?2:1]}</option>`).join('')}</select></div><div class="field"><label for="inst-${i}">${t('institution')}</label><input id="inst-${i}" value="${esc(a.institution)}" oninput="updateAsset(${i},'institution',this.value)"></div></div><div class="field"><label for="nom-${i}">${t('nomineeSet')}</label><select id="nom-${i}" onchange="updateAsset(${i},'hasNominee',this.value==='yes')"><option value="no" ${!a.hasNominee?'selected':''}>${t('no')}</option><option value="yes" ${a.hasNominee?'selected':''}>${t('yes')}</option></select></div>${a.hasNominee?`<div class="fields"><div class="field"><label for="name-${i}">${t('nomineeName')}</label><input id="name-${i}" value="${esc(a.nominee)}" oninput="updateAsset(${i},'nominee',this.value)"></div><div class="field"><label for="rel-${i}">${t('relation')}</label><input id="rel-${i}" value="${esc(a.relation)}" oninput="updateAsset(${i},'relation',this.value)"></div><div class="field"><label for="year-${i}">${t('updated')}</label><input id="year-${i}" type="number" min="1990" max="2026" value="${esc(a.year)}" oninput="updateAsset(${i},'year',this.value)"></div></div>`:''}<button class="btn danger" type="button" onclick="removeAsset(${i})">${t('remove')}</button></article>`; }
function door1Add(){ if(!state.assets.length) addAsset(); return `<a class="back" href="#/">${t('back')}</a><div class="screen-head"><div><div class="step">I / ${t('d1')}</div><h2>${t('addTitle')}</h2><p>${t('addSub')}</p></div></div><div class="form-stack">${state.assets.map(assetForm).join('')}</div><div class="actions"><button class="btn" onclick="addAsset()">${t('addAsset')}</button><button class="btn primary" onclick="go('/door1/check')">${t('check')}</button></div>`; }
function door1Check(){ const facts=[FACTS.nominee,FACTS.insurance,FACTS.banks,FACTS.personalLaw]; return `<a class="back" href="#/door1/add">${t('back')}</a><div class="step">I / ${t('d1')}</div><h2>${t('checkTitle')}</h2><p>${t('checkSub')}</p>${state.assets.length?state.assets.map(a=>`<div class="panel"><div class="screen-head"><div><h3>${esc(typeLabel(a.type))}</h3><div>${esc(a.institution)||'—'}</div></div>${status(completeness(a))}</div>${completeness(a)==='missing'?`<p>${t('fixMissing')}</p>`:completeness(a)==='outdated'?`<p>${t('fixOld')}</p>`:''}</div>`).join(''):`<div class="empty">${t('noAssets')}</div>`}<div class="fact">${verify(FACTS.nominee)}<h3>${t('explainer')}</h3><p>${state.lang==='hi'?FACTS.nominee.hi:FACTS.nominee.en}</p></div><p class="disclaimer">${t('generalRule')}</p><div class="actions"><button class="btn" onclick="go('/door1/will')">${t('draft')}</button><button class="btn primary" onclick="go('/door1/sheet')">${t('handover')}</button></div>`; }
function door1Will(){ if(!state.beneficiaries.length)state.beneficiaries.push({name:'',relation:'',what:''}); return `<a class="back" href="#/door1/check">${t('back')}</a><div class="step">I / ${t('draft')}</div><h2>${t('draft')}</h2><div class="warn">${t('draftWarning')}</div><p>${t('draftSub')}</p><div class="form-stack"><div class="field"><label for="testator">${t('testator')}</label><input id="testator" value="${esc(state.testator)}" oninput="state.testator=this.value"></div>${state.beneficiaries.map((b,i)=>`<article class="asset-card"><h3>${t('beneficiary')} ${i+1}</h3><div class="fields"><div class="field"><label>${t('beneficiary')}</label><input value="${esc(b.name)}" oninput="state.beneficiaries[${i}].name=this.value"></div><div class="field"><label>${t('relation')}</label><input value="${esc(b.relation)}" oninput="state.beneficiaries[${i}].relation=this.value"></div><div class="field"><label>${t('whatThey')}</label><input value="${esc(b.what)}" oninput="state.beneficiaries[${i}].what=this.value"></div></div></article>`).join('')}</div><div class="actions"><button class="btn" onclick="state.beneficiaries.push({name:'',relation:'',what:''});render()">${t('addBeneficiary')}</button><button class="btn primary" onclick="state.draft=true;render()">${t('makeDraft')}</button></div>${state.draft?`<article class="panel" id="draft-output"><div class="stamp-wrap"><span class="stamp">${t('stamp')}<br>${t('brand')}</span></div><div class="warn">${t('draftWarning')}</div><h3>${esc(state.testator)||'—'}</h3><ul>${state.beneficiaries.filter(b=>b.name).map(b=>`<li>${esc(b.name)} (${esc(b.relation)||'—'}) — ${esc(b.what)||'—'}</li>`).join('')||'<li>—</li>'}</ul><h3>${t('willChecklist')}</h3><ul>${CHECKLISTS.will[state.lang].map(x=>`<li>${x}</li>`).join('')}</ul><button class="btn" onclick="window.print()">${t('print')}</button></article>`:''}`; }
function door1Sheet(){ const rows=state.assets.map(a=>`<tr><td>${esc(typeLabel(a.type))}</td><td>${esc(a.institution)||'—'}</td><td>${a.hasNominee?`${esc(a.nominee)||'—'} (${esc(a.relation)||'—'})`:'—'}</td><td>${status(completeness(a))}</td></tr>`).join(''); return `<a class="back" href="#/door1/check">${t('back')}</a><div class="step">I / ${t('handover')}</div><h2>${t('sheetTitle')}</h2><p>${t('sheetSub')}</p><div class="panel table-wrap"><table class="record-table"><thead><tr><th>${t('type')}</th><th>${t('institution')}</th><th>${t('currentNominee')}</th><th>${t('status')}</th></tr></thead><tbody>${rows||`<tr><td colspan="4">${t('noAssets')}</td></tr>`}</tbody></table></div>${state.share?`<div class="panel"><div class="stamp-wrap"><span class="stamp">${t('stamp')}<br>${t('brand')}</span></div><p>${t('shared')} <strong>${esc(state.share.recipient)}</strong></p><button class="btn danger" onclick="state.share=null;render()">${t('revoke')}</button></div>`:`<div class="actions"><button class="btn brass" onclick="state.share={pending:true,recipient:''};render()">${t('share')}</button></div>`}${state.share?.pending?`<div class="share-preview"><h3>${t('shareTitle')}</h3><p>${t('shareSub')}</p><div class="mono">${state.assets.map(a=>`${esc(typeLabel(a.type))} / ${esc(a.institution)||'—'} / ${a.hasNominee?esc(a.nominee)||'—':'—'}`).join('<br>')||'—'}</div><div class="field"><label for="recipient">${t('recipient')}</label><input id="recipient" oninput="state.share.recipient=this.value"></div><div class="actions"><button class="btn danger" onclick="state.share=null;render()">${t('cancel')}</button><button class="btn primary" onclick="if(state.share.recipient.trim()){state.share={recipient:state.share.recipient.trim(),fields:['assets','completeness','nominees'],revoked:false,sharedAt:new Date().toISOString()};render()}">${t('confirmShare')}</button></div></div>`:''}`; }
function door2(){ return `<a class="back" href="#/">${t('back')}</a><div class="step">II / ${t('d2')}</div><h2>${t('lostTitle')}</h2><p>${t('lostSub')}</p><div class="form-stack"><div class="fields"><div class="field"><label for="person">${t('person')}</label><input id="person"></div><div class="field"><label for="years">${t('years')}</label><input id="years"></div></div><button class="btn primary" onclick="runSearch()">${t('search')}</button></div><div id="search-results">${state.search?results():''}</div>`; }
function runSearch(){ state.search='searching';render(); setTimeout(()=>{state.search='done';render()},650); }
function results(){ if(state.search==='searching')return `<div class="panel search-log">${REGISTRIES.map((r,i)=>`<div style="animation-delay:${i*.1}s">${t('searching')} ${r}…</div>`).join('')}</div>`; return `<h3>${t('matches')}</h3>${MATCHES.map(m=>`<article class="result"><div><div class="eyebrow">${m.registry}</div><div class="amount">₹${m.amount.toLocaleString('en-IN')}</div></div><div><span class="confidence ${m.confidence}">${t(m.confidence)}</span><br><a href="#/door2/match/${m.id}">${t('viewChecklist')}</a></div></article>`).join('')}<div class="honesty">${t('simulated')}</div>`; }
function match(id){ const m=MATCHES.find(x=>x.id===id)||MATCHES[0]; return `<a class="back" href="#/door2/search">${t('back')}</a><div class="step">II / ${m.registry}</div><h2>₹${m.amount.toLocaleString('en-IN')}</h2><div class="panel"><div class="eyebrow">${m.registry} · ${t(m.confidence)}</div><h3>${t('claimTitle')}</h3><p>${t('claimNote')}</p><ul>${CHECKLISTS.claim[state.lang].map(x=>`<li>${x}</li>`).join('')}</ul></div><div class="honesty">${t('simulated')}</div>`; }
function door3(){ return `<a class="back" href="#/">${t('back')}</a><div class="step">III / ${t('d3')}</div><h2>${t('rightsTitle')}</h2><p>${t('rightsSub')}</p><div class="branch-grid">${[['lostRelative','/door3/lost'],['setup','/door3/setup'],['pressure','/door3/pressure'],['dispute','/door3/dispute']].map((x,i)=>`<button class="branch" onclick="go('${x[1]}')"><span>0${i+1}</span>${t(x[0])}</button>`).join('')}</div>`; }
function branch(kind){ let body=''; if(kind==='lost')body=`<div class="fact">${verify(FACTS.nominee)}<p>${FACTS[state.lang==='hi'?'nominee':'nominee'][state.lang]}</p></div><div class="panel"><ul>${CHECKLISTS.claim[state.lang].map(x=>`<li>${x}</li>`).join('')}</ul></div>`; if(kind==='setup')body=`<div class="fact">${verify(FACTS.personalLaw)}<p>${FACTS.personalLaw[state.lang]}</p></div><div class="panel"><ul>${CHECKLISTS.nominee[state.lang].map(x=>`<li>${x}</li>`).join('')}</ul></div>`; if(kind==='pressure')body=`<div class="fact">${verify(FACTS.elder)}<p>${FACTS.elder[state.lang]}</p></div>${escalation()}`; if(kind==='dispute')body=escalation(); return `<a class="back" href="#/door3">${t('back')}</a><div class="step">III / ${t('next')}</div><h2>${t('next')}</h2>${body}<p class="disclaimer">${t('generalRule')}</p>`; }
function escalation(){return `<div class="panel"><h3>${t('escalation')}</h3><ul>${ESCALATION.map(e=>`<li>${verify(e)}${e[state.lang]}</li>`).join('')}</ul></div>`;}
function newHome(){ return `<section class="family-hero"><div><div class="eyebrow">${t('familyEyebrow')}</div><h1>${t('familyTitle')}</h1><p class="hero-copy">${t('familySub')}</p><p class="hero-promise">${t('familyPromise')}</p></div><div class="hero-note"><div class="mono">${t('independent')}</div><div class="hero-note-mark">OR</div></div></section><section class="state-intro"><div class="eyebrow">${t('homeEyebrow')}</div><h2>${t('homeTitle')}</h2><p>${t('homeSub')}</p></section><section class="state-grid"><a class="state-card" href="#/door1/add"><span class="state-number">01</span><span class="state-title">${t('prepareTitle')}</span><span class="state-desc">${t('prepareDesc')}</span><span class="state-action">${t('startPrepare')}</span></a><a class="state-card" href="#/handover"><span class="state-number">02</span><span class="state-title">${t('handoverTitle')}</span><span class="state-desc">${t('handoverDesc')}</span><span class="state-action">${t('startHandover')}</span></a><a class="state-card" href="#/door3"><span class="state-number">03</span><span class="state-title">${t('resolveTitle')}</span><span class="state-desc">${t('resolveDesc')}</span><span class="state-action">${t('startResolve')}</span></a></section>`; }
function handover(){ return `<a class="back" href="#/">${t('back')}</a><div class="step">02 / ${t('handoverEyebrow')}</div><h2>${t('handoverTitle')}</h2><p>${t('handoverSub')}</p><div class="handover-steps"><div class="panel"><h3>${t('handoverStep1')}</h3><p>${t('sheetSub')}</p></div><div class="panel"><h3>${t('handoverStep2')}</h3><p>${t('claimNote')}</p></div><div class="panel"><h3>${t('handoverStep3')}</h3><p>${t('generalRule')}</p></div></div><div class="honesty">${t('mockBoundary')}</div><div class="actions"><button class="btn primary" onclick="go('/door2/search')">${t('startHandover')}</button><button class="btn" onclick="go('/door3')">${t('startResolve')}</button></div>`; }
function render(){ const h=location.hash.replace('#','')||'/'; let html=newHome(); if(h==='/door1/add')html=door1Add();else if(h==='/door1/check')html=door1Check();else if(h==='/door1/will')html=door1Will();else if(h==='/door1/sheet')html=door1Sheet();else if(h==='/handover')html=handover();else if(h==='/door2/search')html=door2();else if(h.startsWith('/door2/match/'))html=match(h.split('/').pop());else if(h==='/door3')html=door3();else if(h.startsWith('/door3/'))html=branch(h.split('/').pop()); layout(html); }
function render(){ const h=location.hash.replace('#','')||'/'; let html=home(); if(h==='/door1/add')html=door1Add();else if(h==='/door1/check')html=door1Check();else if(h==='/door1/will')html=door1Will();else if(h==='/door1/sheet')html=door1Sheet();else if(h==='/door2/search')html=door2();else if(h.startsWith('/door2/match/'))html=match(h.split('/').pop());else if(h==='/door3')html=door3();else if(h.startsWith('/door3/'))html=branch(h.split('/').pop()); layout(html); }
