Object.assign(STRINGS, { recordRef:{en:'Record reference (synthetic)',hi:'Record reference (synthetic)'}, documentLocation:{en:'Where is the document kept?',hi:'Document कहां रखा है?'}, recordNotes:{en:'Short note (optional)',hi:'Short note (optional)'}, syntheticHint:{en:'Use fictional details only. Do not enter real account numbers or IDs.',hi:'केवल fictional details लिखें। असली account numbers या IDs न लिखें।'}, handoverPerson:{en:'Name of the person who died (synthetic)',hi:'जिस व्यक्ति की मृत्यु हुई उनका नाम (synthetic)'}, deathCertificate:{en:'Death certificate available?',hi:'क्या death certificate उपलब्ध है?'}, willFound:{en:'Will or draft found?',hi:'क्या will या draft मिला है?'}, available:{en:'Available',hi:'उपलब्ध'}, notSure:{en:'Not sure yet',hi:'अभी पता नहीं'}, missingDoc:{en:'Not available yet',hi:'अभी उपलब्ध नहीं'}, beginHandover:{en:'Create handover checklist →',hi:'Handover checklist बनाएं →'}, handoverChecklistTitle:{en:'Your handover checklist',hi:'आपकी handover checklist'}, handoverChecklistSub:{en:'A practical list for the first conversation with an institution or authority.',hi:'Institution या authority से पहली बातचीत के लिए practical list।'}, openSearch:{en:'Check possible records →',hi:'Possible records check करें →'}, openPrepare:{en:'Open family record',hi:'Family record खोलें'} });
