function assetForm(a,i){ return `<article class="asset-card"><span class="asset-index mono">${String(i+1).padStart(2,'0')}</span><div class="fields"><div class="field"><label for="type-${i}">${t('type')}</label><select id="type-${i}" onchange="updateAsset(${i},'type',this.value)">${ASSET_TYPES.map(x=>`<option value="${x[0]}" ${a.type===x[0]?'selected':''}>${x[state.lang==='hi'?2:1]}</option>`).join('')}</select></div><div class="field"><label for="inst-${i}">${t('institution')}</label><input id="inst-${i}" value="${esc(a.institution)}" oninput="updateAsset(${i},'institution',this.value)"></div><div class="field"><label for="ref-${i}">${t('recordRef')}</label><input id="ref-${i}" value="${esc(a.reference||'')}" placeholder="e.g. MOCK-001" oninput="updateAsset(${i},'reference',this.value)"></div><div class="field"><label for="loc-${i}">${t('documentLocation')}</label><input id="loc-${i}" value="${esc(a.documentLocation||'')}" placeholder="e.g. Home file" oninput="updateAsset(${i},'documentLocation',this.value)"></div></div><p class="field-hint">${t('syntheticHint')}</p><div class="field"><label for="nom-${i}">${t('nomineeSet')}</label><select id="nom-${i}" onchange="updateAsset(${i},'hasNominee',this.value==='yes')"><option value="no" ${!a.hasNominee?'selected':''}>${t('no')}</option><option value="yes" ${a.hasNominee?'selected':''}>${t('yes')}</option></select></div>${a.hasNominee?`<div class="fields"><div class="field"><label for="name-${i}">${t('nomineeName')}</label><input id="name-${i}" value="${esc(a.nominee||'')}" oninput="updateAsset(${i},'nominee',this.value)"></div><div class="field"><label for="rel-${i}">${t('relation')}</label><input id="rel-${i}" value="${esc(a.relation||'')}" oninput="updateAsset(${i},'relation',this.value)"></div><div class="field"><label for="year-${i}">${t('updated')}</label><input id="year-${i}" type="number" min="1990" max="2026" value="${esc(a.year||'')}" oninput="updateAsset(${i},'year',this.value)"></div></div>`:''}<div class="field"><label for="note-${i}">${t('recordNotes')}</label><input id="note-${i}" value="${esc(a.notes||'')}" oninput="updateAsset(${i},'notes',this.value)"></div><button class="btn danger" type="button" onclick="removeAsset(${i})">${t('remove')}</button></article>`; }
function door1Add(){ return `<a class="back" href="#/">${t('back')}</a><div class="step">01 / ${t('prepareTitle')}</div><h2>${t('addTitle')}</h2><p>${t('addSub')}</p><div class="form-stack">${state.assets.map(assetForm).join('')}</div><div class="actions"><button class="btn" onclick="addAsset()">${t('addAsset')}</button><button class="btn primary" onclick="go('/door1/check')">${t('check')}</button></div>`; }
function handover(){ const c=state.handoverCase; return `<a class="back" href="#/">${t('back')}</a><div class="step">02 / ${t('handoverEyebrow')}</div><h2>${t('handoverTitle')}</h2><p>${t('handoverSub')}</p>${!c.started?`<div class="handover-intake panel"><h3>${t('handoverChecklistTitle')}</h3><p>${t('handoverChecklistSub')}</p><div class="form-stack"><div class="field"><label for="handover-person">${t('handoverPerson')}</label><input id="handover-person" value="${esc(c.person)}" oninput="updateHandover('person',this.value)"></div><div class="fields"><div class="field"><label for="death-cert">${t('deathCertificate')}</label><select id="death-cert" onchange="updateHandover('deathCertificate',this.value)"><option value="notSure" ${c.deathCertificate==='notSure'?'selected':''}>${t('notSure')}</option><option value="available" ${c.deathCertificate==='available'?'selected':''}>${t('available')}</option><option value="missing" ${c.deathCertificate==='missing'?'selected':''}>${t('missingDoc')}</option></select></div><div class="field"><label for="will-found">${t('willFound')}</label><select id="will-found" onchange="updateHandover('willFound',this.value)"><option value="notSure" ${c.willFound==='notSure'?'selected':''}>${t('notSure')}</option><option value="available" ${c.willFound==='available'?'selected':''}>${t('available')}</option><option value="missing" ${c.willFound==='missing'?'selected':''}>${t('missingDoc')}</option></select></div></div><button class="btn primary" onclick="beginHandover()">${t('beginHandover')}</button></div></div>`:`<div class="panel"><div class="eyebrow">${esc(c.person)||'—'}</div><h3>${t('handoverChecklistTitle')}</h3><p>${t('handoverChecklistSub')}</p><ul><li>${CHECKLISTS.claim[state.lang][0]}</li><li>${c.deathCertificate==='available'?t('available'):t('deathCertificate')}</li><li>${c.willFound==='available'?t('available'):t('willFound')}</li><li>${t('sheetSub')}</li></ul><div class="actions"><button class="btn primary" onclick="go('/door2/search')">${t('openSearch')}</button><button class="btn" onclick="go('/door1/add')">${t('openPrepare')}</button></div></div>`}<div class="honesty">${t('mockBoundary')}</div>`; }
