function tPlatform(k){ const value=STRINGS[k]?.[state.lang]||STRINGS[k]?.en||k; return String(value).replace(/\s*—\s*/g,', '); }
function platformHome(){ const m=platformModel(); return platformWrap(`<div class="service-hero"><div><div class="service-kicker">${t('serviceName')}</div><h1>${t('serviceName')}</h1><p class="service-lede">${t('serviceIntro')}</p><p class="service-prompt">${t('serviceQuestion')}</p><p class="service-question-sub">${t('serviceQuestionSub')}</p></div><div class="service-id">${t('serviceId')}<br><span class="demo-badge">${t('demoLabel')}</span></div></div><div class="service-alert"><strong>${t('important')}</strong><span>${t('serviceNotice')}</span></div><div class="demo-banner"><div><strong>${t('demoLabel')}</strong><p>${t('demoSub')}</p></div><button class="btn" onclick="seedDemo()">${t('clearDemo')}</button></div><div class="service-section-title"><div><h2>${t('serviceSummary')}</h2><p>${t('serviceCaseDesc')}</p></div></div><div class="case-summary"><div class="summary-cell"><div class="summary-label">${t('summaryPeople')}</div><div class="summary-value">1</div></div><div class="summary-cell"><div class="summary-label">${t('summaryRecords')}</div><div class="summary-value">${state.assets.length}</div></div><div class="summary-cell"><div class="summary-label">${t('summaryTasks')}</div><div class="summary-value">${m.tasks.length}</div></div><div class="summary-cell"><div class="summary-label">${t('summaryCases')}</div><div class="summary-value">1</div></div></div><div class="service-section-title"><div><h2>${t('serviceCase')}</h2><p>${t('serviceCaseDesc')}</p></div></div><div class="service-grid"><a class="service-card" href="#/door1/add"><span class="service-status">01 · ${t('railPrepare')}</span><h3>${t('servicePrepare')}</h3><p>${t('servicePrepareDesc')}</p><span class="next-action">${t('serviceNext')}</span></a><a class="service-card" href="#/handover"><span class="service-status">02 · ${t('railHandover')}</span><h3>${t('serviceHandover')}</h3><p>${t('serviceHandoverDesc')}</p><span class="next-action">${t('serviceNext')}</span></a><a class="service-card" href="#/door3"><span class="service-status">03 · ${t('railResolve')}</span><h3>${t('serviceResolve')}</h3><p>${t('serviceResolveDesc')}</p><span class="next-action">${t('serviceNext')}</span></a></div><section class="proof-section"><div class="service-section-title"><div><h2>${t('proofTitle')}</h2><p>${t('sourceLabel')}</p></div></div><div class="proof-grid"><div class="proof-card"><strong>${t('proof1Value')}</strong><span>${t('proof1Label')}</span><small>${verify(FACTS.banks)}</small></div><div class="proof-card"><strong>${t('proof2Value')}</strong><span>${t('proof2Label')}</span><small>${verify({confidence:'verified'})}</small></div><div class="proof-card"><strong>${t('proof3Value')}</strong><span>${t('proof3Label')}</span><small>${verify({confidence:'verified'})}</small></div></div></section>`, 'home'); }
function renderApp(){ const h=location.hash.replace('#','')||'/'; let html=platformHome(); if(h==='/door1/add')html=platformScreen(door1Add(),'prepare');else if(h==='/door1/check')html=platformScreen(door1Check(),'prepare');else if(h==='/door1/will')html=platformScreen(door1Will(),'prepare');else if(h==='/door1/sheet')html=platformScreen(door1Sheet(),'prepare');else if(h==='/handover')html=platformScreen(handover(),'handover');else if(h==='/door2/search')html=platformScreen(door2(),'handover');else if(h.startsWith('/door2/match/'))html=platformScreen(match(h.split('/').pop()),'handover');else if(h==='/door3')html=platformScreen(door3(),'resolve');else if(h.startsWith('/door3/'))html=platformScreen(branch(h.split('/').pop()),'resolve'); layout(html); }
renderApp();
function door1Check(){ return `<a class="back" href="#/door1/add">${t('back')}</a><div class="step">01 / ${t('prepareTitle')}</div><h2>${t('checkTitle')}</h2><p>${t('checkSub')}</p>${state.assets.length?state.assets.map(a=>`<div class="panel"><div class="screen-head"><div><h3>${esc(typeLabel(a.type))}</h3><div>${esc(a.institution)||'—'}</div><div class="record-meta mono">${esc(a.reference)||'—'} · ${esc(a.documentLocation)||'—'}</div></div>${status(completeness(a))}</div>${completeness(a)==='missing'?`<p>${t('fixMissing')}</p>`:completeness(a)==='outdated'?`<p>${t('fixOld')}</p>`:''}</div>`).join(''):`<div class="empty">${t('noAssets')}</div>`}<div class="fact">${verify(FACTS.nominee)}<h3>${t('explainer')}</h3><p>${FACTS.nominee[state.lang]}</p></div><p class="disclaimer">${t('generalRule')}</p><div class="actions"><button class="btn" onclick="go('/door1/will')">${t('draft')}</button><button class="btn primary" onclick="go('/door1/sheet')">${t('handover')}</button></div>`; }
function door1Sheet(){ const rows=state.assets.map(a=>`<tr><td>${esc(typeLabel(a.type))}</td><td>${esc(a.institution)||'—'}<br><span class="mono">${esc(a.reference)||'—'}</span></td><td>${esc(a.documentLocation)||'—'}</td><td>${a.hasNominee?`${esc(a.nominee)||'—'} (${esc(a.relation)||'—'})`:'—'}</td><td>${status(completeness(a))}</td></tr>`).join(''); return `<a class="back" href="#/door1/check">${t('back')}</a><div class="step">01 / ${t('handover')}</div><h2>${t('sheetTitle')}</h2><p>${t('sheetSub')}</p><div class="panel table-wrap"><table class="record-table"><thead><tr><th>${t('type')}</th><th>${t('institution')} / ${t('recordRef')}</th><th>${t('documentLocation')}</th><th>${t('currentNominee')}</th><th>${t('status')}</th></tr></thead><tbody>${rows||`<tr><td colspan="5">${t('noAssets')}</td></tr>`}</tbody></table></div>${state.share?`<div class="panel"><div class="stamp-wrap"><span class="stamp">${t('stamp')}<br>${t('brand')}</span></div><p>${t('shared')} <strong>${esc(state.share.recipient)}</strong></p><button class="btn danger" onclick="state.share=null;render()">${t('revoke')}</button></div>`:`<div class="actions"><button class="btn brass" onclick="state.share={pending:true,recipient:''};render()">${t('share')}</button></div>`}${state.share?.pending?`<div class="share-preview"><h3>${t('shareTitle')}</h3><p>${t('shareSub')}</p><div class="mono">${state.assets.map(a=>`${esc(typeLabel(a.type))} / ${esc(a.institution)||'—'} / ${esc(a.reference)||'—'} / ${esc(a.documentLocation)||'—'}`).join('<br>')||'—'}</div><div class="field"><label for="recipient">${t('recipient')}</label><input id="recipient" oninput="state.share.recipient=this.value"></div><div class="actions"><button class="btn danger" onclick="state.share=null;render()">${t('cancel')}</button><button class="btn primary" onclick="if(state.share.recipient.trim()){state.share={recipient:state.share.recipient.trim(),fields:['assets','references','documentLocations','completeness','nominees'],revoked:false,sharedAt:new Date().toISOString()};render()}">${t('confirmShare')}</button></div></div>`:''}`; }
Object.assign(STRINGS,{heroKicker:{en:'Family Continuity Service / Independent prototype',hi:'Family Continuity Service / Independent prototype'},heroTitle:{en:'When a family member dies, start with one clear case.',hi:'जब परिवार का कोई सदस्य नहीं रहता, एक clear case से शुरू करें।'},heroBody:{en:'On Record helps a family see what is recorded, identify what is missing, and reach the official service that handles the next step.',hi:'On Record family को recorded जानकारी देखने, missing चीजें पहचानने और next step की official service तक पहुंचने में मदद करता है।'},heroPrimary:{en:'Start the demo case →',hi:'Demo case शुरू करें →'},heroSecondary:{en:'Prepare records',hi:'Records prepare करें'},scenarioTitle:{en:'Meera is organising her father’s records.',hi:'Meera अपने पिता के records organise कर रही है।'},scenarioBody:{en:'She has a bank record, a property paper, and an insurance policy. The family needs a shared starting point, not another place to guess.',hi:'उसके पास bank record, property paper और insurance policy है। Family को guess करने की एक और जगह नहीं, एक shared starting point चाहिए।'},scenarioCase:{en:'DEMO CASE / FC-001',hi:'DEMO CASE / FC-001'},scenarioFact1:{en:'3 records found in the family papers',hi:'Family papers में 3 records मिले'},scenarioFact2:{en:'1 nominee detail needs attention',hi:'1 nominee detail पर ध्यान चाहिए'},scenarioFact3:{en:'0 live government systems contacted',hi:'0 live government systems contacted'},startQuestion:{en:'Start with your situation',hi:'अपनी situation से शुरू करें'},startSub:{en:'Choose one path. All three paths use the same family case.',hi:'एक path चुनें। तीनों paths इसी family case का इस्तेमाल करते हैं।'},timelineTitle:{en:'One case, three moments',hi:'एक case, तीन moments'},timelineSub:{en:'The service stays connected as the family moves from preparation to action.',hi:'Family preparation से action तक जाए, service connected रहती है।'},timeline1:{en:'Prepare',hi:'Prepare'},timeline1d:{en:'Record what exists before it becomes urgent.',hi:'Urgent होने से पहले जो मौजूद है उसे record करें।'},timeline2:{en:'Handover',hi:'Handover'},timeline2d:{en:'Turn scattered papers into a first checklist after a death.',hi:'Death के बाद scattered papers को first checklist में बदलें।'},timeline3:{en:'Route',hi:'Route'},timeline3d:{en:'Take a neutral summary to the right public authority.',hi:'Neutral summary सही public authority तक ले जाएं।'},officialTitle:{en:'Where official services fit',hi:'Official services यहां जुड़ती हैं'},officialSub:{en:'On Record prepares the context. These public services handle the official process.',hi:'On Record context prepare करता है। Official process ये public services handle करती हैं।'},openOfficial:{en:'Open official service ↗',hi:'Official service खोलें ↗'},contextTitle:{en:'Why this needs a clearer first step',hi:'इसमें clearer first step क्यों जरूरी है'},contextSub:{en:'Public systems are valuable, but families still have to know what to search for and where to begin.',hi:'Public systems valuable हैं, लेकिन family को फिर भी पता होना चाहिए कि क्या search करना है और कहां से शुरू करना है।'},officialBoundary:{en:'These links are destinations only. This prototype does not send data or submit a claim.',hi:'ये links सिर्फ destinations हैं। यह prototype data भेजता या claim submit नहीं करता।'}});
var OFFICIAL_DESTINATIONS=[{name:'RBI UDGAM',kind:'Unclaimed bank deposits',url:'https://udgam.rbi.org.in',desc:'Search facility for unclaimed bank deposits.'},{name:'IEPF',kind:'Shares and dividends',url:'https://www.iepf.gov.in',desc:'Investor Education and Protection Fund services.'},{name:'Bima Bharosa',kind:'Insurance',url:'https://bimabharosa.irdai.gov.in',desc:'Insurance grievance and service pathway.'},{name:'EPFO',kind:'Provident fund',url:'https://www.epfindia.gov.in',desc:'Provident fund member and claim services.'},{name:'MF Central',kind:'Mutual funds',url:'https://www.mfcentral.com',desc:'Mutual fund account and service access.'},{name:'NALSA',kind:'Legal aid and settlement',url:'https://nalsa.gov.in',desc:'Legal aid, Lok Adalat, mediation, and state links.'}];
function destinationCards(){ return (OFFICIAL_DESTINATIONS||[]).map(d=>`<article class="official-card"><div class="official-kind">${esc(d.kind)}</div><h3>${esc(d.name)}</h3><p>${esc(d.desc)}</p><a href="${d.url}" target="_blank" rel="noreferrer">${t('openOfficial')}</a></article>`).join(''); }
function platformHome(){ return platformWrap(`<section class="case-hero-grid"><div class="case-hero"><div class="service-kicker">${t('heroKicker')}</div><h1>${t('heroTitle')}</h1><p>${t('heroBody')}</p><div class="hero-actions"><a class="btn primary" href="#/handover">${t('heroPrimary')}</a><a class="btn" href="#/door1/add">${t('heroSecondary')}</a></div></div><aside class="case-scenario"><div class="case-code">${t('scenarioCase')}</div><h2>${t('scenarioTitle')}</h2><p>${t('scenarioBody')}</p><ul><li>${t('scenarioFact1')}</li><li>${t('scenarioFact2')}</li><li>${t('scenarioFact3')}</li></ul></aside></section><div class="service-alert"><strong>${t('important')}</strong><span>${t('serviceNotice')}</span></div><section class="start-section"><div class="service-section-title"><div><h2>${t('startQuestion')}</h2><p>${t('startSub')}</p></div><span class="demo-badge">${t('demoLabel')}</span></div><div class="situation-list"><a class="situation-row" href="#/door1/add"><span class="situation-number">01</span><span><strong>${t('servicePrepare')}</strong><small>${t('servicePrepareDesc')}</small></span><span class="situation-arrow">→</span></a><a class="situation-row" href="#/handover"><span class="situation-number">02</span><span><strong>${t('serviceHandover')}</strong><small>${t('serviceHandoverDesc')}</small></span><span class="situation-arrow">→</span></a><a class="situation-row" href="#/door3"><span class="situation-number">03</span><span><strong>${t('serviceResolve')}</strong><small>${t('serviceResolveDesc')}</small></span><span class="situation-arrow">→</span></a></div></section><section class="timeline-section"><div class="service-section-title"><div><h2>${t('timelineTitle')}</h2><p>${t('timelineSub')}</p></div></div><div class="case-timeline"><a href="#/door1/add" class="timeline-item"><span class="timeline-index">01</span><span><strong>${t('timeline1')}</strong><small>${t('timeline1d')}</small></span></a><a href="#/handover" class="timeline-item"><span class="timeline-index">02</span><span><strong>${t('timeline2')}</strong><small>${t('timeline2d')}</small></span></a><a href="#/door3" class="timeline-item"><span class="timeline-index">03</span><span><strong>${t('timeline3')}</strong><small>${t('timeline3d')}</small></span></a></div></section><section class="official-section"><div class="service-section-title"><div><h2>${t('officialTitle')}</h2><p>${t('officialSub')}</p></div></div><div class="official-grid">${destinationCards()}</div><div class="honesty">${t('officialBoundary')}</div></section><section class="context-section"><div class="service-section-title"><div><h2>${t('contextTitle')}</h2><p>${t('contextSub')}</p></div></div><div class="proof-grid"><div class="proof-card"><strong>${t('proof1Value')}</strong><span>${t('proof1Label')}</span><small>${verify(FACTS.banks)||'Source-bounded figure'}</small></div><div class="proof-card"><strong>${t('proof2Value')}</strong><span>${t('proof2Label')}</span><small>Approximate figure</small></div><div class="proof-card"><strong>${t('proof3Value')}</strong><span>${t('proof3Label')}</span><small>Reported settlement scale</small></div></div></section>`,'home'); }
function renderApp(){ const h=location.hash.replace('#','')||'/'; let html=platformHome(); if(h==='/door1/add')html=platformScreen(door1Add(),'prepare');else if(h==='/door1/check')html=platformScreen(door1Check(),'prepare');else if(h==='/door1/will')html=platformScreen(door1Will(),'prepare');else if(h==='/door1/sheet')html=platformScreen(door1Sheet(),'prepare');else if(h==='/handover')html=platformScreen(handover(),'handover');else if(h==='/door2/search')html=platformScreen(door2(),'handover');else if(h.startsWith('/door2/match/'))html=platformScreen(match(h.split('/').pop()),'handover');else if(h==='/door3')html=platformScreen(door3(),'resolve');else if(h.startsWith('/door3/'))html=platformScreen(branch(h.split('/').pop()),'resolve'); layout(html); }
renderApp();
